import re,os,glob
def mod2path(m):
    return m.replace('.','/')+'.lean'
all_files={os.path.relpath(p) for p in glob.glob('AlgebraicJacobian/**/*.lean',recursive=True)}
def imports(path):
    out=[]
    try: txt=open(path).read()
    except: return out
    for line in txt.splitlines():
        line=line.strip()
        if line.startswith('import '):
            m=line.split()[1]
            if m.startswith('AlgebraicJacobian'): out.append(mod2path(m))
        elif line and not line.startswith('--') and not line.startswith('/-'):
            break
    return out
seen=set(); stack=imports('AlgebraicJacobian.lean')
while stack:
    p=stack.pop()
    if p in seen: continue
    seen.add(p)
    for q in imports(p):
        if q not in seen: stack.append(q)
reach=seen & all_files
unreach=sorted(all_files-reach)
print('total .lean under AlgebraicJacobian/:',len(all_files))
print('reachable from root (transitive):',len(reach))
print('UNREACHABLE:',len(unreach))
from collections import Counter
print('unreachable by dir:',dict(Counter(os.path.dirname(u) for u in unreach)))
hw=[u for u in unreach if 'DivSchemeHighWindow' in u]
print('DivSchemeHighWindow* among them:',len(hw))
